import { Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { GRADES, Grade } from '../../core/people';
import { Sheets } from '../../core/sheet';

// The sheet's grades, each shown retired or not, and a form to retire one.
@Component({
  selector: 'app-grades',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="grades-heading">
      <h2 id="grades-heading">Grades</h2>
      <ul aria-label="Grades">
        @for (g of grades; track g) {
          <li [attr.data-testid]="'grade-row-' + g">
            Grade {{ g }}, retired: <span data-testid="grade-retired">{{ retired().has(g) ? 'yes' : 'no' }}</span>
          </li>
        }
      </ul>
      <form [formGroup]="form" (ngSubmit)="retire()" aria-label="Retire a grade">
        <label for="grade-retire-select">Grade to retire</label>
        <select id="grade-retire-select" data-testid="grade-retire-select" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="grade-retire" [disabled]="saving()">Retire grade</button>
        @if (error(); as err) {
          <p role="alert" data-testid="grade-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class GradesPanel {
  private readonly sheets = inject(Sheets);

  protected readonly grades = GRADES;
  protected readonly retired = computed(() => new Set(this.sheets.current()?.retiredGrades ?? []));
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected readonly form = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
  });

  constructor() {
    toObservable(this.sheets.loaded)
      .pipe(takeUntilDestroyed())
      .subscribe(() => this.error.set(null));
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected retire(): void {
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const { grade } = this.form.getRawValue();
    this.saving.set(true);
    this.sheets.retireGrade(sheet.id, grade).subscribe({
      next: () => this.saving.set(false),
      error: () => {
        this.saving.set(false);
        this.error.set(`Grade ${grade} could not be retired: it is already retired.`);
      },
    });
  }
}
  /** Change the active sheet's proof kinds (comma separated); null means none. Not dated. */
  setProofKinds(id: string, proofKinds: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/proof-kinds`, { proofKinds })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Change the active sheet's default grade; null means none (then A). Not dated. */
  setDefaultGrade(id: string, defaultGrade: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/default-grade`, { defaultGrade })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Retire a grade on the active sheet; refused for one already retired. */
  retireGrade(id: string, grade: string): Observable<SheetView> {
    return this.http
      .post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/grades/${grade}/retire`, null)
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Change the active sheet's alert threshold; null means off. Not dated. */
  setAlertThreshold(id: string, alertThreshold: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/alert-threshold`, { alertThreshold })
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Change the active sheet's parent sheet; null means none. Not dated. */
  setParent(id: string, parent: string | null): Observable<SheetView> {
    return this.http
    public SheetView setProofKinds(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ProofKindsChange request) {
        String kinds = request.proofKinds() == null || request.proofKinds().isEmpty() ? null : request.proofKinds();
        return SheetView.of(sheets.setProofKinds(id, user, kinds));
    }

    /** Change the sheet's default grade. */
    @PutMapping("/{id}/settings/default-grade")
    public SheetView setDefaultGrade(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody DefaultGradeChange request) {
        String grade = request.defaultGrade() == null || request.defaultGrade().isEmpty() ? null : request.defaultGrade();
        return SheetView.of(sheets.setDefaultGrade(id, user, grade));
    }

    /** Retire a grade. */
    @PostMapping("/{id}/grades/{grade}/retire")
    public SheetView retireGrade(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @PathVariable @Pattern(regexp = "[ABC]") String grade) {
        return SheetView.of(sheets.retireGrade(id, user, grade));
    }

    /** Change the sheet's parent sheet. */
    @PutMapping("/{id}/settings/parent")
    public SheetView setParent(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ParentChange request) {
        String parent = request.parent() == null || request.parent().isEmpty() ? null : request.parent();
        return SheetView.of(sheets.setParent(id, user, parent));
    }
    /** Set the sheet's default grade (A, B or C; null: none, then A), starting the sheet if it has never been loaded.
     *  Not dated; no one's grade changes with it. */
    @Transactional
    public Sheet setDefaultGrade(String id, String user, String grade) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        sheet.setDefaultGrade(grade);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=default-grade value=" + (grade == null ? "" : grade));
        return saved;
    }

    /** Retire a grade (A, B or C), starting the sheet if it has never been loaded: it can no longer be given to a new
     *  person nor chosen in an edit; people on it keep it. Refused for a grade already retired. Not dated. */
    @Transactional
    public Sheet retireGrade(String id, String user, String grade) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        if (sheet.isGradeRetired(grade)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Grade " + grade + " is already retired");
        }
        sheet.retireGrade(grade);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "GRADE_RETIRED sheet=" + id + " by=" + user + " grade=" + grade);
        return saved;
    }

    /** Set the sheet's parent sheet (null: none), starting the sheet if it has never been loaded. Not dated. Refused
     *  for the sheet itself, for a sheet never loaded, and for a sheet that has this one as an ancestor. */
    @Transactional
    public Sheet setParent(String id, String user, String parentId) {
        if (parentId != null) {
            if (parentId.equals(id)) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A sheet cannot be its own parent");
            }

